[package]
name = "word-frequency"
version = "0.1.0"
edition = "2021"

[dependencies]
E
cat > src/main.rs <<'E'
use std::collections::HashMap;
use std::io::Write;
use std::process::ExitCode;

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: word-frequency <file>");
        return ExitCode::from(2);
    };
    let data = match std::fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error reading {}: {e}", path.to_string_lossy());
            return ExitCode::from(1);
        }
    };

    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in data.split(|b| !b.is_ascii_alphanumeric()).filter(|w| !w.is_empty()) {
        let key = word.to_ascii_lowercase();
        *counts.entry(key).or_insert(0) += 1;
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for (word, count) in entries.into_iter().take(10) {
        let _ = out.write_all(&word);
        let _ = writeln!(out, " {count}");
    }
    ExitCode::SUCCESS
}
